+        match bytes[new_off] {
+            b' ' => {
+                new_off += 1;
+                new_col += 1;
+            }
+            b'\t' => {
+                new_col += 4 - (new_col % 4);
+                new_off += 1;
+            }
+            _ => {}
+        }
+    }
+    Some((new_col, new_off))
